pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        bool reverted = false;
        try c.assertionDisputedCallback(assertionId) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }
}

